    public CrewRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's crews with their leads and members, each in the order they were added. */
    public List<Crew> findAll(String sheetId) {
        Map<Long, Crew> crews = new LinkedHashMap<>();
